css:
[data-slot="button"]{border-radius:999px!important;font-weight:700;}
[data-slot="input"],[data-slot="select-trigger"]{border-radius:999px!important;}
[data-thread-item]{border-radius:6px!important;}
[data-slot="composer-host"]{border-radius:24px!important;border:1px solid transparent!important;box-shadow:none!important;background:var(--input)!important;transition:border-color .15s;}
[data-slot="composer-host"]:hover{border-color:color-mix(in srgb,var(--foreground) 15%,transparent)!important;}
[data-slot="composer-host"]:focus-within{border-color:var(--foreground)!important;}
button.bg-message-action{border-radius:999px!important;}
button.bg-message-action:not(:disabled):hover{transform:scale(1.04);}
[data-user-message-bubble]{border-radius:8px!important;}
.chat-markdown-codeblock{border-radius:8px!important;border:none;}
[data-slot="dialog-popup"]{border-radius:8px!important;border:none!important;box-shadow:0 16px 24px rgba(0,0,0,.3),0 6px 8px rgba(0,0,0,.2)!important;}
[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:4px!important;border:none!important;box-shadow:0 16px 24px rgba(0,0,0,.3),0 6px 8px rgba(0,0,0,.2)!important;}
[data-slot="tooltip-popup"]{border-radius:4px!important;}
button.bg-message-action:disabled{background:color-mix(in srgb,var(--foreground) 12%,transparent)!important;color:var(--muted-foreground)!important;opacity:1!important;}
.dark [data-slot="switch"][data-unchecked]{background:#535353!important;box-shadow:none!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#B3B3B3!important;box-shadow:none!important;}
[data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
[data-slot="switch"][data-checked]{background:#1ED760!important;box-shadow:none!important;}
[data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#000000!important;}
::-webkit-scrollbar{width:12px;height:12px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 25%,transparent);border-radius:0;border:2px solid transparent;background-clip:padding-box;}
::-webkit-scrollbar-thumb:hover{background-color:color-mix(in srgb,var(--foreground) 40%,transparent);}
